using Microsoft.Extensions.AI;
using OpenAI;
using System.ComponentModel;

Console.WriteLine("Research Agent Starting...");

// Configure the chat client with tool support
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";

IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// Set up the research tools
var researchTools = new ResearchTools();
var chatOptions = new ChatOptions
{
    Tools = [
        AIFunctionFactory.Create(researchTools.SearchWeb),
        AIFunctionFactory.Create(researchTools.TakeNote),
        AIFunctionFactory.Create(researchTools.GetNotes),
    ]
};

// Get the research topic
Console.Write("\nEnter a topic to research: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

// Run the agent loop
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information (perform multiple searches with different queries)
        2. Taking notes on key findings as you go
        3. After gathering enough information, reviewing your notes and providing a comprehensive summary

        Always take notes on important findings before moving to the next search.
        When you have enough information, retrieve all your notes and write a final summary.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

var response = await client.GetResponseAsync(messages, chatOptions);
Console.WriteLine("\n=== Research Summary ===\n");
Console.WriteLine(response.Text);

// Display collected notes
var notes = researchTools.GetAllNotes();
if (notes.Count > 0)
{
    Console.WriteLine("\n=== Research Notes ===\n");
    for (int i = 0; i < notes.Count; i++)
    {
        Console.WriteLine($"  {i + 1}. {notes[i]}");
    }
}

/// <summary>
/// Tools available to the research agent.
/// </summary>
sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _httpClient = new();

    [Description("Search the web for information on a query. Returns search result snippets.")]
    public async Task<string> SearchWeb([Description("The search query")] string query)
    {
        Console.WriteLine($"  [Tool] Searching: \"{query}\"");
        try
        {
            // Use a public search API (DuckDuckGo instant answer)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var response = await _httpClient.GetStringAsync(url);

            using var doc = System.Text.Json.JsonDocument.Parse(response);
            var root = doc.RootElement;

            var results = new List<string>();

            // Extract abstract
            var abstractText = root.GetProperty("Abstract").GetString();
            if (!string.IsNullOrEmpty(abstractText))
                results.Add($"Summary: {abstractText}");

            // Extract related topics
            if (root.TryGetProperty("RelatedTopics", out var related))
            {
                foreach (var item in related.EnumerateArray().Take(5))
                {
                    if (item.TryGetProperty("Text", out var text))
                        results.Add($"- {text.GetString()}");
                }
            }

            if (results.Count == 0)
                return $"No detailed results found for '{query}'. Try a different search query.";

            return string.Join("\n", results);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Take a note to remember an important finding during research.")]
    public string TakeNote([Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note taken ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all notes taken during this research session.")]
    public string GetNotes()
    {
        Console.WriteLine($"  [Tool] Retrieving {_notes.Count} notes");
        if (_notes.Count == 0)
            return "No notes have been taken yet.";

        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }

    public List<string> GetAllNotes() => [.. _notes];
}

